
const WORDS=[{"id": 0, "w": "朝三暮四", "p": "zhāosān mùsì", "t": "成语", "m": "thay đổi thất thường", "coll": "做事朝三暮四、不能朝三暮四", "s": "做事情不能朝三暮四，要坚持自己的目标。"}, {"id": 1, "w": "词汇", "p": "cíhuì", "t": "名词", "m": "từ vựng", "coll": "积累词汇、扩大词汇量", "s": "多读书可以帮助我们积累词汇。"}, {"id": 2, "w": "固定", "p": "gùdìng", "t": "形容词／动词", "m": "cố định; ổn định", "coll": "固定的时间、固定工作", "s": "我们每周在固定的时间上汉语课。"}, {"id": 3, "w": "结构", "p": "jiégòu", "t": "名词", "m": "kết cấu, cấu trúc", "coll": "文章结构、句子结构", "s": "写作文前，要先想好文章的结构。"}, {"id": 4, "w": "整体", "p": "zhěngtǐ", "t": "名词", "m": "chỉnh thể, toàn thể", "coll": "从整体来看、整体安排", "s": "我们不能只看一部分，还要从整体来看问题。"}, {"id": 5, "w": "综合", "p": "zōnghé", "t": "动词／形容词", "m": "tổng hợp lại; tổng hợp", "coll": "综合意见、综合分析", "s": "老师综合了大家的意见，重新安排了活动。"}, {"id": 6, "w": "完整", "p": "wánzhěng", "t": "形容词", "m": "hoàn chỉnh, trọn vẹn", "coll": "完整的故事、内容完整", "s": "请用自己的话讲一个完整的故事。"}, {"id": 7, "w": "哲学家", "p": "zhéxuéjiā", "t": "名词", "m": "nhà triết học", "coll": "一位哲学家、哲学家的思想", "s": "他正在阅读一位哲学家的著作。"}, {"id": 8, "w": "寓言", "p": "yùyán", "t": "名词", "m": "truyện ngụ ngôn", "coll": "一则寓言、寓言故事", "s": "这则寓言告诉了我们一个简单而深刻的道理。"}, {"id": 9, "w": "喂养", "p": "wèiyǎng", "t": "动词", "m": "nuôi", "coll": "喂养动物、喂养宠物", "s": "小女孩每天都认真地喂养自己的小猫。"}, {"id": 10, "w": "群", "p": "qún", "t": "量词", "m": "bầy, đàn", "coll": "一群孩子、一群猴子", "s": "一群孩子在公园里高兴地做游戏。"}, {"id": 11, "w": "猴子", "p": "hóuzi", "t": "名词", "m": "con khỉ", "coll": "一只猴子、猴子的尾巴", "s": "树上的那只猴子正抱着一根树枝荡来荡去。"}, {"id": 12, "w": "宠物", "p": "chǒngwù", "t": "名词", "m": "vật cưng, thú cưng", "coll": "养宠物、宠物食品", "s": "养宠物之前，要想清楚自己是否有时间照顾它。"}, {"id": 13, "w": "相处", "p": "xiāngchǔ", "t": "动词", "m": "chung sống", "coll": "友好相处、相处融洽", "s": "我们虽然来自不同的地方，却相处得很好。"}, {"id": 14, "w": "彼此", "p": "bǐcǐ", "t": "名词", "m": "hai bên", "coll": "彼此了解、彼此帮助", "s": "在学习上，同学们应该彼此帮助。"}, {"id": 15, "w": "表情", "p": "biǎoqíng", "t": "名词", "m": "nét mặt, vẻ mặt", "coll": "脸上的表情、惊讶的表情", "s": "从他脸上的表情，我看出他很惊讶。"}, {"id": 16, "w": "行为", "p": "xíngwéi", "t": "名词", "m": "hành vi, hành động", "coll": "文明行为、不良行为", "s": "在公共场所大声说话是不文明的行为。"}, {"id": 17, "w": "对方", "p": "duìfāng", "t": "名词", "m": "đối phương, phía bên kia", "coll": "理解对方、尊重对方", "s": "讨论问题时，我们应该认真听取对方的意见。"}, {"id": 18, "w": "蔬菜", "p": "shūcài", "t": "名词", "m": "rau cải", "coll": "新鲜蔬菜、种蔬菜", "s": "奶奶在院子里种了许多新鲜的蔬菜。"}, {"id": 19, "w": "粮食", "p": "liángshi", "t": "名词", "m": "lương thực", "coll": "节约粮食、储存粮食", "s": "我们应该珍惜粮食，不要浪费。"}, {"id": 20, "w": "家庭", "p": "jiātíng", "t": "名词", "m": "gia đình", "coll": "幸福的家庭、家庭生活", "s": "在这个幸福的家庭里，每个人都关心着彼此。"}, {"id": 21, "w": "财产", "p": "cáichǎn", "t": "名词", "m": "tài sản, của cải", "coll": "家庭财产、保护财产", "s": "每个人都应该保护好自己的合法财产。"}, {"id": 22, "w": "消费", "p": "xiāofèi", "t": "动词", "m": "tiêu thụ, tiêu dùng", "coll": "理性消费、消费习惯", "s": "购物时，我们应该理性消费。"}, {"id": 23, "w": "节省", "p": "jiéshěng", "t": "动词", "m": "tiết kiệm, dành dụm", "coll": "节省时间、节省开支", "s": "坐地铁去公司，可以节省很多时间。"}, {"id": 24, "w": "限制", "p": "xiànzhì", "t": "动词", "m": "hạn chế", "coll": "限制人数、限制使用", "s": "为了保证活动质量，这次活动限制了参加人数。"}, {"id": 25, "w": "猪", "p": "zhū", "t": "名词", "m": "heo", "coll": "一头猪、养猪", "s": "爷爷以前在农村养过几头猪。"}, {"id": 26, "w": "调皮", "p": "tiáopí", "t": "形容词", "m": "nghịch ngợm, tinh nghịch", "coll": "调皮的孩子、十分调皮", "s": "弟弟十分调皮，总喜欢躲在门后吓我。"}, {"id": 27, "w": "淘气", "p": "táoqì", "t": "形容词", "m": "nghịch ngợm", "coll": "淘气的孩子、别淘气", "s": "那个淘气的孩子又偷偷地把我的帽子藏起来了。"}, {"id": 28, "w": "橡子", "p": "xiàngzi", "t": "名词", "m": "quả đấu, hạt dẻ rừng", "coll": "捡橡子、一颗橡子", "s": "孩子们在树下捡到了几颗橡子。"}, {"id": 29, "w": "果实", "p": "guǒshí", "t": "名词", "m": "quả, trái cây", "coll": "树上的果实、成熟的果实", "s": "到了秋天，树上的果实渐渐成熟了。"}, {"id": 30, "w": "不足", "p": "bùzú", "t": "形容词／动词", "m": "thiếu; không đủ", "coll": "时间不足、准备不足", "s": "由于准备不足，他这次没有通过考试。"}, {"id": 31, "w": "倒", "p": "dào", "t": "副词", "m": "lại (chỉ sự trái ngược)", "coll": "我倒觉得、倒也不错", "s": "大家都说这个办法不好，我倒觉得可以试一试。"}, {"id": 32, "w": "馒头", "p": "mántou", "t": "名词", "m": "màn thầu", "coll": "一个馒头、蒸馒头", "s": "早饭时，他吃了一个馒头，喝了一碗粥。"}, {"id": 33, "w": "颗", "p": "kē", "t": "量词", "m": "hạt, viên", "coll": "一颗星星、一颗糖", "s": "她从口袋里拿出一颗糖。"}, {"id": 34, "w": "似乎", "p": "sìhū", "t": "副词", "m": "dường như", "coll": "似乎明白、似乎有点儿累", "s": "他今天似乎有点儿累，一直没怎么说话。"}, {"id": 35, "w": "吃亏", "p": "chī kuī", "t": "动词", "m": "chịu thiệt, thiệt thòi", "coll": "吃了亏、不要吃亏", "s": "买东西前多比较一下，就不容易吃亏。"}, {"id": 36, "w": "方式", "p": "fāngshì", "t": "名词", "m": "phương thức, cách thức", "coll": "学习方式、生活方式", "s": "每个人都有适合自己的学习方式。"}, {"id": 37, "w": "安慰", "p": "ānwèi", "t": "动词", "m": "an ủi, dỗ dành", "coll": "安慰朋友、轻声安慰", "s": "看到朋友难过，她轻声地安慰了几句。"}, {"id": 38, "w": "要不", "p": "yàobù", "t": "连词", "m": "nếu không thì", "coll": "要不这样、要不改天", "s": "今天太晚了，要不我们明天再讨论吧。"}, {"id": 39, "w": "显得", "p": "xiǎnde", "t": "动词", "m": "tỏ ra, có vẻ", "coll": "显得年轻、显得很高兴", "s": "穿上这件衣服，她显得更年轻了。"}, {"id": 40, "w": "格外", "p": "géwài", "t": "副词", "m": "vô cùng, hết sức", "coll": "格外认真、格外高兴", "s": "听说妈妈要来，她今天显得格外高兴。"}, {"id": 41, "w": "情景", "p": "qíngjǐng", "t": "名词", "m": "tình cảnh, cảnh tượng", "coll": "当时的情景、热闹的情景", "s": "多年以后，我仍然记得当时的情景。"}, {"id": 42, "w": "哈", "p": "hā", "t": "拟声词／叹词", "m": "(tiếng cười) ha ha", "coll": "哈哈大笑、哈，真有趣", "s": "哈，这个故事真有趣！"}];
const CHUNKS=[["做事情", "不能", "朝三暮四，", "要坚持自己的目标。"], ["多读书", "可以", "帮助我们", "积累词汇。"], ["我们", "每周", "在固定的时间", "上汉语课。"], ["写作文前，", "要", "先想好", "文章的结构。"], ["我们", "不能", "只看一部分，", "还要从整体来看问题。"], ["老师", "综合了", "大家的意见，", "重新安排了活动。"], ["请", "用自己的话", "讲一个", "完整的故事。"], ["他", "正在", "阅读", "一位哲学家的著作。"], ["这则寓言", "告诉了我们", "一个", "简单而深刻的道理。"], ["小女孩", "每天", "都认真地", "喂养自己的小猫。"], ["一群孩子", "在公园里", "高兴地", "做游戏。"], ["树上的那只猴子", "正", "抱着一根树枝", "荡来荡去。"], ["养宠物之前，", "要", "想清楚", "自己是否有时间照顾它。"], ["我们", "虽然", "来自不同的地方，", "却相处得很好。"], ["在学习上，", "同学们", "应该", "彼此帮助。"], ["从", "他脸上的表情，", "我", "看出他很惊讶。"], ["在公共场所", "大声说话", "是", "不文明的行为。"], ["讨论问题时，", "我们", "应该", "认真听取对方的意见。"], ["奶奶", "在院子里", "种了", "许多新鲜的蔬菜。"], ["我们", "应该", "珍惜粮食，", "不要浪费。"], ["在", "这个幸福的家庭里，", "每个人", "都关心着彼此。"], ["每个人", "都应该", "保护好", "自己的合法财产。"], ["购物时，", "我们", "应该", "理性消费。"], ["坐地铁", "去公司，", "可以", "节省很多时间。"], ["为了保证活动质量，", "这次活动", "限制了", "参加人数。"], ["爷爷", "以前", "在农村", "养过几头猪。"], ["弟弟", "十分调皮，", "总喜欢", "躲在门后吓我。"], ["那个淘气的孩子", "又", "偷偷地", "把我的帽子藏起来了。"], ["孩子们", "在树下", "捡到了", "几颗橡子。"], ["到了秋天，", "树上的果实", "渐渐", "成熟了。"], ["由于", "准备不足，", "他", "这次没有通过考试。"], ["大家", "都说这个办法不好，", "我", "倒觉得可以试一试。"], ["早饭时，", "他", "吃了一个馒头，", "喝了一碗粥。"], ["她", "从口袋里", "拿出", "一颗糖。"], ["他", "今天", "似乎有点儿累，", "一直没怎么说话。"], ["买东西前", "多比较一下，", "就", "不容易吃亏。"], ["每个人", "都有", "适合自己的", "学习方式。"], ["看到朋友难过，", "她", "轻声地", "安慰了几句。"], ["今天", "太晚了，", "要不", "我们明天再讨论吧。"], ["穿上这件衣服，", "她", "显得", "更年轻了。"], ["听说妈妈要来，", "她", "今天", "显得格外高兴。"], ["多年以后，", "我", "仍然", "记得当时的情景。"], ["哈，", "这个故事", "真", "有趣！"]];
'use strict';
const root=document.getElementById('ntc-design-preview');
const $=id=>document.getElementById(id);
const STORE='ngocthucac-hsk5-bai8-learning-v3';
const pages=['词汇表','学习生词','词汇卡片','综合练习','连词成句','学习统计'];
let storageOK=true,store={active:null,profiles:{}};
try{let raw=localStorage.getItem(STORE);if(raw){let parsed=JSON.parse(raw);if(parsed&&parsed.profiles)store=parsed}}catch(e){storageOK=false}
let student=store.active?store.profiles[store.active]:null;
if(!student){store.active='local';student=store.profiles.local||createStudent('','');store.profiles.local=student;}
let ui=student?.ui||{page:0,g:0,idx:0,pinyin:false};
let speed=1,playback=null,audioGeneration=0;
const group=g=>WORDS.slice(g*10,g===3?WORDS.length:g*10+10);
const groupOf=id=>Math.min(3,Math.floor(id/10));
const escapeHTML=t=>String(t).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const hasLearned=id=>!!student?.studied.includes(id);
const learned=g=>group(g).filter(d=>hasLearned(d.id)).length;
const allLearned=()=>!!student&&student.studied.length===WORDS.length;
const memory=id=>student?.memory[id]||'new';
const weakIds=()=>WORDS.filter(d=>memory(d.id)==='review').map(d=>d.id);
const totalLearned=()=>student?.studied.length||0;
const currentWord=()=>group(ui.g)[ui.idx];
function shuffle(a){let b=[...a];for(let i=b.length-1;i>0;i--){let j=Math.floor(Math.random()*(i+1));[b[i],b[j]]=[b[j],b[i]]}return b}
function toast(message){let t=$('ntc-toast');t.textContent=message;t.hidden=false;clearTimeout(toast.timer);toast.timer=setTimeout(()=>t.hidden=true,5000)}
function save(){if(student){student.ui={...ui};student.updatedAt=new Date().toISOString()}try{localStorage.setItem(STORE,JSON.stringify(store))}catch(e){storageOK=false;toast('浏览器无法保存学习进度，请允许保存本地数据。')}}
function createStudent(name,clas){return {name,clas,studied:[],memory:{},bookmark:{g:0,idx:0},ui:{page:0,g:0,idx:0,pinyin:false},flash:null,quiz:null,order:null,quizHistory:[],orderHistory:[],timeMs:0}}
function status(id){if(!hasLearned(id))return '<span class="ntc-state new">○ 未学习</span>';if(memory(id)==='review')return '<span class="ntc-state review">↻ 需要复习</span>';return '<span class="ntc-state">✓ 已学习</span>'}
function button(label,action,cls='',disabled=false){return `<button data-action="${action}" class="${cls}" ${disabled?'disabled':''}>${label}</button>`}
function go(page){stopAudio();ui.page=page;if(student&&allLearned()){if(page===2&&!student.flash)startFlash('all',false);if(page===3&&!student.quiz)startQuiz(false);if(page===4&&!student.order)startOrder(null,false)}save();render()}
function chooseGroup(g){stopAudio();ui.g=g;ui.idx=0;ui.page=1;save();render()}
function heading(title,subtitle='',tag=''){return `<div class="ntc-sectionhead"><div><h2>${title}</h2>${subtitle?`<p class="ntc-caption">${subtitle}</p>`:''}</div>${tag?`<span class="ntc-tag">${tag}</span>`:''}</div>`}
function meter(value,total){return `<div class="ntc-meter" role="progressbar" aria-label="进度" aria-valuenow="${value}" aria-valuemin="0" aria-valuemax="${total}"><span style="width:${total?value/total*100:0}%"></span></div>`}
function gate(){return `<div class="ntc-panel ntc-lock"><div class="ntc-kicker">先学习生词，再进行全课复习</div><h2>请先完成生词学习</h2><p>已学习 ${totalLearned()}/43 个词语。学完四组词语后，即可进行词汇卡片、综合练习和连词成句。</p>${meter(totalLearned(),43)}<div class="ntc-progressgroups">${[0,1,2,3].map(g=>`<button data-group="${g}">组别 ${g+1}<br>${learned(g)}/${group(g).length}个词语</button>`).join('')}</div>${button('继续学习 →','resume','ntc-primary')}</div>`}
function listView(){return `<div class="ntc-panel">${heading('词汇表','全课共43个词语，点击 ↗ 学习该词语',totalLearned()+'/43 已学习')}<div class="ntc-tablewrap"><table class="ntc-table"><thead><tr><th>汉字</th><th class="ntc-colpinyin">拼音</th><th class="ntc-coltype">词性</th><th>越南语释义</th><th>状态</th></tr></thead><tbody>${WORDS.map((d,i)=>`<tr><td class="ntc-hanzi">${d.w} <button class="ntc-play" data-word="${i}" aria-label="学习词语 ${d.w}">↗</button><button class="ntc-play" data-audio-word="${i}" aria-label="听词语 ${d.w}">◖</button></td><td class="ntc-colpinyin">${escapeHTML(d.p)}</td><td class="ntc-coltype">${escapeHTML(d.t)}</td><td>${escapeHTML(d.m)}</td><td>${status(i)}</td></tr>`).join('')}</tbody></table></div><div class="ntc-actions"><span class="ntc-caption">仅生词学习分为四组：10、10、10、13个词语。</span>${button('开始／继续学习 →','resume','ntc-primary')}</div></div>`}
function studyView(){let d=currentWord(),a=group(ui.g),isLast=d.id===42;return `<div class="ntc-panel">${heading('学习生词 · 组别 '+(ui.g+1),'学习词语、搭配与例句',`${ui.idx+1}/${a.length}`)}${meter(learned(ui.g),a.length)}<div class="ntc-study"><div class="ntc-wordbox"><div class="ntc-pinyin" style="visibility:${ui.pinyin?'visible':'hidden'}">${escapeHTML(d.p)}</div><div class="ntc-bigword ntc-writing" id="ntc-writing" aria-label="汉字笔顺">${d.w}</div><div class="ntc-meaning">${escapeHTML(d.m)}</div><span class="ntc-type">${escapeHTML(d.t)}</span><div class="ntc-smallbtns">${button('笔顺演示','strokes')}<button data-audio-word="${d.id}">◖ 听词语</button>${button(ui.pinyin?'隐藏拼音':'显示拼音','pinyin')}</div></div><div><div class="ntc-label">常用搭配</div><div class="ntc-cn">${escapeHTML(d.coll)}</div><hr><div class="ntc-label">例句</div><div class="ntc-cn">${escapeHTML(d.s)}</div><div class="ntc-smallbtns"><button data-audio-example="${d.id}">◖ 听例句</button></div><div class="ntc-note">${status(d.id)}</div></div></div><div class="ntc-actions">${button('← 上一个','prev-study','',d.id===0)}${button(isLast?'✓ 已学习 · 全课复习 →':ui.idx===a.length-1?'✓ 已学习 · 下一组 →':'✓ 已学习 · 下一个 →','mark-study','ntc-primary')}</div><div class="ntc-footnote">点击“已学习”记录学习进度。需要时，可点击“笔顺演示”查看汉字的书写顺序。</div></div>`}
function markStudy(){let d=currentWord();if(!student.studied.includes(d.id))student.studied.push(d.id);let next=WORDS.find(x=>!student.studied.includes(x.id));if(d.id<42){let id=d.id+1;ui.g=groupOf(id);ui.idx=id-ui.g*10;student.bookmark={g:ui.g,idx:ui.idx}}else if(!next){ui.page=2;student.bookmark={g:3,idx:12};if(!student.flash)startFlash('all',false)}else{ui.g=groupOf(next.id);ui.idx=next.id-ui.g*10;student.bookmark={g:ui.g,idx:ui.idx};toast('还有未学完的词语，请继续学习。')}save();render()}
function startFlash(filter='all',redraw=true){let ids=filter==='weak'?weakIds():WORDS.map(d=>d.id);if(!ids.length){toast('暂无需要复习的词语。');return}student.flash={filter,ids:shuffle(ids),at:0,flipped:false,ratings:{},done:false};save();if(redraw)render()}
function flashView(){let f=student.flash;if(f.done)f.done=false;let d=WORDS[f.ids[f.at]];return `<div class="ntc-panel">${heading('词汇卡片 · 全课复习',f.filter==='weak'?'复习练习中答错的词语':'全课43个词语随机排列，不分组',`${f.at+1}/${f.ids.length}`)}${meter(f.at+1,f.ids.length)}<div class="ntc-smallbtns" style="margin-bottom:16px">${button('重新打乱全课43个词语','flash-all')}${button('待复习词语 ('+weakIds().length+')','flash-weak','',!weakIds().length)}</div><div class="ntc-flash"><span class="ntc-label">${f.flipped?'背面':'正面'}</span>${f.flipped?`<span class="ntc-pinyin">${escapeHTML(d.p)}</span><span class="ntc-meaning">${escapeHTML(d.m)}</span><span class="ntc-type">${escapeHTML(d.t)}</span><small>${escapeHTML(d.coll)}</small><div class="ntc-note"><span class="ntc-cn">${escapeHTML(d.s)}</span><button class="ntc-play" data-audio-example="${d.id}" aria-label="听例句">◖</button></div>`:`<div style="display:flex;align-items:center;justify-content:center;gap:12px"><span class="ntc-bigword" style="font-size:clamp(40px,${d.w.length>2?'7':'10'}vw,${d.w.length>2?'80':'112'}px)">${d.w}</span><button class="ntc-play" data-audio-word="${d.id}" aria-label="听发音 ${d.w}" title="听发音">🔊</button></div>`}<div class="ntc-smallbtns">${button(f.flipped?'↶ 返回正面':'查看释义与例句 ↻','flip')}</div></div><div class="ntc-actions">${button('← 上一张','flash-prev','',f.at===0)}${f.at===f.ids.length-1?button('综合练习 →','quiz-page','ntc-primary'):button('下一张 →','flash-next','ntc-primary')}</div><div class="ntc-footnote">先看正面回忆词义；需要时翻到背面查看拼音、释义与例句。无需翻面即可切换卡片。</div></div>`}
const contextAlternatives={"0": [6, 27, 30], "1": [6, 27, 30], "2": [6, 27, 30], "3": [6, 27, 30], "4": [6, 27, 30], "5": [6, 27, 30], "6": [6, 27, 30], "7": [6, 27, 30], "8": [6, 27, 30], "9": [6, 27, 30], "10": [6, 27, 30], "11": [3, 19, 28], "12": [6, 27, 30], "13": [6, 27, 30], "14": [3, 19, 28], "15": [6, 27, 30], "16": [6, 27, 30], "17": [3, 19, 28], "18": [6, 27, 30], "19": [6, 27, 30], "20": [6, 27, 30], "21": [6, 27, 30], "22": [6, 27, 30], "23": [6, 27, 30], "24": [6, 27, 30], "25": [6, 27, 30], "26": [3, 19, 28], "27": [6, 27, 30], "28": [6, 27, 30], "29": [6, 27, 30], "30": [6, 27, 30], "31": [6, 27, 30], "32": [6, 27, 30], "33": [6, 27, 30], "34": [6, 27, 30], "35": [3, 19, 28], "36": [6, 27, 30], "37": [6, 27, 30], "38": [3, 19, 28], "39": [6, 27, 30], "40": [6, 27, 30], "41": [2, 13, 34], "42": [6, 27, 30]};
function makeQuestions(ids){let types=ids.map(id=>id%3===2?'context':id%3===0?'listen':'meaning');let positions=shuffle(ids.map((_,i)=>i%4));return shuffle(ids.map((id,i)=>{let alternatives=types[i]==='context'?contextAlternatives[id]:null;let opts=alternatives?shuffle(alternatives):shuffle(WORDS.filter(d=>d.id!==id&&!((id===26&&d.id===27)||(id===27&&d.id===26))).map(d=>d.id)).slice(0,3);opts.splice(positions[i],0,id);return {id,type:types[i],opts,correct:positions[i],picked:null}}))}
function startQuiz(redraw=true,ids=null){student.quiz={questions:makeQuestions(ids||WORDS.map(d=>d.id)),at:0,done:false,recorded:false};save();if(redraw)render()}
function quizView(){let q=student.quiz;if(q.done)return quizResults();let x=q.questions[q.at],d=WORDS[x.id],answered=x.picked!==null;return `<div class="ntc-panel">${heading('综合练习','听音选词 · 根据越南语释义选词 · 选词填空',`${q.at+1}/${q.questions.length}题`)}${meter(q.at,q.questions.length)}<div class="ntc-label">${x.type==='listen'?'听一听 · 听音选词':x.type==='meaning'?'认一认 · 根据越南语释义选词':'用一用 · 选词填空'}</div>${x.type==='listen'?`<button data-audio-word="${d.id}" class="ntc-primary">◖ 听词语</button><div class="ntc-footnote">如设备没有中文语音，可切换为根据越南语释义选词。</div>${button('切换为释义题','quiz-as-meaning','',answered)}`:x.type==='meaning'?`<div class="ntc-note">请根据越南语释义选择正确的汉语词语： <strong>${escapeHTML(d.m)}</strong></div>`:`<div class="ntc-cn">${escapeHTML(d.s.replace(d.w,'____'))}</div>`}<div class="ntc-quizopts">${x.opts.map((id,i)=>`<button data-answer="${i}" ${answered?'disabled':''} class="${answered?(i===x.correct?'ntc-correct':i===x.picked?'ntc-wrong':''):''}">${'ABCD'[i]}. ${WORDS[id].w}</button>`).join('')}</div>${answered?`<div class="ntc-note" role="status"><strong>${x.picked===x.correct?'✓ 正确':'✕ 不正确'}</strong><div class="ntc-cn">${d.w} · ${escapeHTML(d.p)}</div>${escapeHTML(d.m)}<br>${escapeHTML(d.s)}</div><div class="ntc-actions"><button data-audio-example="${d.id}">◖ 听例句</button>${button(q.at===q.questions.length-1?'查看结果 →':'下一题 →','quiz-next','ntc-primary')}</div>`:''}</div>`}
function pickQuiz(i){let q=student.quiz,x=q.questions[q.at];if(x.picked!==null)return;x.picked=i;if(i!==x.correct)student.memory[x.id]='review';save();render()}
function nextQuiz(){let q=student.quiz;if(q.questions[q.at].picked===null)return;if(q.at<q.questions.length-1)q.at++;else{q.done=true;if(!q.recorded){student.quizHistory.push({date:new Date().toISOString(),answers:q.questions.map(x=>({id:x.id,ok:x.picked===x.correct})),total:q.questions.length});q.recorded=true}}save();render()}
function quizResults(){let q=student.quiz,wrong=q.questions.filter(x=>x.picked!==x.correct),correct=q.questions.length-wrong.length;return `<div class="ntc-panel">${heading('综合练习结果','正确答案与待复习词语')}<div class="ntc-score">${correct}<small> / ${q.questions.length}题答对</small></div><div class="ntc-tag">${wrong.length}题答错</div>${wrong.map(x=>`<div class="ntc-miniresult"><strong>${WORDS[x.id].w}</strong> · ${escapeHTML(WORDS[x.id].p)}<br>你的选择： ${WORDS[x.opts[x.picked]].w}<br>正确释义： ${escapeHTML(WORDS[x.id].m)}<br>${escapeHTML(WORDS[x.id].s)}</div>`).join('')}<div class="ntc-actions">${button('重新练习全课词语','quiz-restart')}${button('重练错词','quiz-retry','',!wrong.length)}${button('连词成句 →','order-page','ntc-primary')}</div></div>`}
function startOrder(ids=null,redraw=true){let chosen=ids||WORDS.map(d=>d.id);student.order={ids:shuffle(chosen),at:0,bank:[],selected:[],checked:false,answers:[],done:false,recorded:false};newOrderQuestion();save();if(redraw)render()}
function newOrderQuestion(){let o=student.order;o.bank=shuffle(CHUNKS[o.ids[o.at]].map((_,i)=>i));if(o.bank.every((x,i)=>x===i))o.bank.reverse();o.selected=[];o.checked=false}
function orderView(){let o=student.order;if(o.done)return orderResults();let id=o.ids[o.at],d=WORDS[id],chunks=CHUNKS[id],ok=o.selected.every((x,i)=>x===i);return `<div class="ntc-panel">${heading('连词成句 · 全课复习','使用已学的43个例句，题目随机排列',`${o.at+1}/${o.ids.length}题`)}${meter(o.at,o.ids.length)}<div class="ntc-label">重点词语 · ${d.w}</div><p class="ntc-caption">按顺序选择词语，点击已选词语可将其放回。</p><div class="ntc-orderanswer ${o.checked?(ok?'ntc-correct':'ntc-wrong'):''}" aria-label="已排列的句子">${o.selected.length?o.selected.map((index,i)=>`<button data-remove="${i}" ${o.checked?'disabled':''}>${escapeHTML(chunks[index])}</button>`).join(''):'<span class="ntc-caption">请在这里排列句子……</span>'}</div><div class="ntc-chunks" aria-label="待选词语">${o.bank.map(index=>`<button class="${o.selected.includes(index)?'used':''}" data-chunk="${index}" ${o.checked||o.selected.includes(index)?'disabled':''}>${escapeHTML(chunks[index])}</button>`).join('')}</div><div class="ntc-actions"><div class="ntc-smallbtns">${button('↶ 撤销最后一项','order-undo','',!o.selected.length||o.checked)}${button('重新排列','order-clear','',!o.selected.length||o.checked)}</div>${button('检查答案','order-check','ntc-primary',o.selected.length!==chunks.length||o.checked)}</div>${o.checked?`<div class="ntc-note" role="status"><strong>${ok?'✓ 与例句顺序一致':'✕ 与例句顺序不一致'}</strong><div class="ntc-label">原例句</div><div class="ntc-cn">${escapeHTML(d.s)}</div><button data-audio-example="${id}">◖ 听例句</button></div><div class="ntc-actions"><span></span>${button(o.at===o.ids.length-1?'查看结果 →':'下一题 →','order-next','ntc-primary')}</div>`:''}<div class="ntc-footnote">本练习按原例句顺序评分，其他语序也可能符合语法。</div></div>`}
function addChunk(index){let o=student.order;if(o.checked||o.selected.includes(index))return;o.selected.push(index);save();render()}
function removeChunk(index){let o=student.order;if(o.checked)return;o.selected.splice(index,1);save();render()}
function checkOrder(){let o=student.order;if(o.checked||o.selected.length!==CHUNKS[o.ids[o.at]].length)return;o.checked=true;let id=o.ids[o.at],ok=o.selected.every((x,i)=>x===i);o.answers.push({id,ok});if(!ok)student.memory[id]='review';save();render()}
function nextOrder(){let o=student.order;if(!o.checked)return;if(o.at<o.ids.length-1){o.at++;newOrderQuestion()}else{o.done=true;if(!o.recorded){student.orderHistory.push({date:new Date().toISOString(),answers:o.answers.map(x=>({...x})),total:o.ids.length});o.recorded=true}}save();render()}
function orderResults(){let o=student.order,wrong=o.answers.filter(x=>!x.ok).map(x=>x.id),correct=o.answers.length-wrong.length;return `<div class="ntc-panel">${heading('连词成句结果','第8课综合复习')}<div class="ntc-score">${correct}<small> / ${o.answers.length}题答对</small></div><div class="ntc-tag">${wrong.length} 题需要重新练习</div>${wrong.map(id=>`<div class="ntc-miniresult"><strong>${WORDS[id].w}</strong><br><span class="ntc-cn">${escapeHTML(WORDS[id].s)}</span></div>`).join('')}<div class="ntc-actions">${button('重新练习全课句子','order-restart')}${button('重练错题','order-retry','',!wrong.length)}${button('查看学习统计 →','stats-page','ntc-primary')}</div></div>`}
function activityScore(kind,g){let history=kind==='quiz'?student.quizHistory:student.orderHistory,record=history[history.length-1],answers=record?.answers||[],ids=group(g).map(d=>d.id),inGroup=answers.filter(x=>ids.includes(x.id));let active=kind==='quiz'?student.quiz:student.order;if(active&&!active.done){let partial=kind==='quiz'?active.questions.filter(x=>x.picked!==null).map(x=>({id:x.id,ok:x.picked===x.correct})):active.answers;inGroup=partial.filter(x=>ids.includes(x.id));if(inGroup.length)return inGroup.filter(x=>x.ok).length+'/'+inGroup.length+' 进行中'}return inGroup.length?inGroup.filter(x=>x.ok).length+'/'+inGroup.length:'尚未练习'}
function statsView(){let weak=weakIds();return `<div class="ntc-panel">${heading('学习统计','当前浏览器中的第8课学习进度','第8课 · 43个词语')}<div class="ntc-statrow"><div class="ntc-stat"><label>已学词语</label><strong>${totalLearned()}<small> / 43</small></strong></div><div class="ntc-stat"><label>需要复习</label><strong>${weak.length}<small>个词语</small></strong></div></div><div class="ntc-tablewrap"><table class="ntc-table"><thead><tr><th>组别</th><th>已学习</th><th>待复习</th><th>综合练习</th><th>连词成句</th></tr></thead><tbody>${[0,1,2,3].map(g=>`<tr><td>组别 ${g+1}<div class="ntc-caption">${group(g).length}个词语</div></td><td>${learned(g)}/${group(g).length}</td><td>${group(g).filter(d=>memory(d.id)==='review').length}</td><td>${activityScore('quiz',g)}</td><td>${activityScore('order',g)}</td></tr>`).join('')}</tbody></table></div><div class="ntc-footnote">按词语所属组显示答对题数／已答题数。优先显示本轮进度，否则显示最近一轮结果。</div><hr><div class="ntc-sectionhead"><h2>待复习词语</h2>${button('用词汇卡片复习 →','flash-weak','',!weak.length||!allLearned())}</div><div class="ntc-terms">${weak.length?weak.map(id=>`<button data-word="${id}">${WORDS[id].w}</button>`).join(''):'<span class="ntc-caption">暂无需要复习的错词。</span>'}</div><div class="ntc-note">继续学习：组别 ${student.bookmark.g+1} · 词语 ${student.bookmark.idx+1}/${group(student.bookmark.g).length}.<br>本页累计学习时间约 ${Math.floor(student.timeMs/60000)} 分钟。已完成综合练习轮数： ${student.quizHistory.length}; 连词成句轮数： ${student.orderHistory.length}.</div><div class="ntc-actions">${button('继续学习','resume','ntc-primary')}${button('导出学习记录','backup')}${button('恢复学习记录','restore')}</div><div class="ntc-footnote">答错词语会列入待复习词语。浏览词汇卡片不等于掌握词语。</div></div>`}
function render(){clearWriting();let total=totalLearned();$('ntc-profile-button').textContent='HSK5 · 第8课';$('ntc-bookmark').textContent=student?total+'/43 个已学词语':'';$('ntc-tabs').innerHTML=pages.map((name,i)=>`<button class="ntc-tab ${ui.page===i?'active':''}" data-page="${i}" aria-pressed="${ui.page===i}">${i<5?i+1+'. ':''}${name}${i>=2&&i<=4&&!allLearned()?' 🔒':''}</button>`).join('');let showGroups=ui.page===1;$('ntc-groups').hidden=!showGroups;$('ntc-groups').innerHTML=showGroups?[0,1,2,3].map(g=>`<button data-group="${g}" class="${g===ui.g?'active':''}">组别 ${g+1} · ${group(g).length}个词语 · ${learned(g)}/${group(g).length}</button>`).join(''):'';$('ntc-sidegroups').innerHTML=showGroups?'<div class="ntc-navtitle">当前词汇组</div>'+[0,1,2,3].map(g=>`<button class="ntc-sidegroup ${g===ui.g?'active':''}" data-group="${g}"><span>组别 ${g+1}<br><small>词语 ${g*10+1}–${g*10+group(g).length}</small></span><small>${learned(g)}/${group(g).length}</small></button>`).join(''):'<div class="ntc-navtitle">第8课学习进度</div><div style="padding:0 10px">'+total+'/43 个已学词语'+meter(total,43)+'</div>';$('ntc-sidefoot').innerHTML='学完生词 →<br>全课综合复习。<br><br>进度保存在<br>当前浏览器中。';let html;if(ui.page>=2&&ui.page<=4&&!allLearned())html=gate();else html=[listView,studyView,flashView,quizView,orderView,statsView][ui.page]();$('ntc-view').innerHTML=html;if(ui.page===1)setupWriting();}
function stopAudio(){audioGeneration++;if(playback){playback.pause();playback=null}if('speechSynthesis' in window)window.speechSynthesis.cancel()}
const AUDIO_INDEX={"朝三暮四":"data:audio/mpeg;base64,","做事情不能朝三暮四，要坚持自己的目标。":"data:audio/mpeg;base64,","词汇":"data:audio/mpeg;base64,","多读书可以帮助我们积累词汇。":"data:audio/mpeg;base64,","固定":"data:audio/mpeg;base64,","我们每周在固定的时间上汉语课。":"data:audio/mpeg;base64,","结构":"data:audio/mpeg;base64,","写作文前，要先想好文章的结构。":"data:audio/mpeg;base64,","整体":"data:audio/mpeg;base64,","我们不能只看一部分，还要从整体来看问题。":"data:audio/mpeg;base64,","综合":"data:audio/mpeg;base64,","老师综合了大家的意见，重新安排了活动。":"data:audio/mpeg;base64,","完整":"data:audio/mpeg;base64,","请用自己的话讲一个完整的故事。":"data:audio/mpeg;base64,","哲学家":"data:audio/mpeg;base64,","他正在阅读一位哲学家的著作。":"data:audio/mpeg;base64,","寓言":"data:audio/mpeg;base64,","这则寓言告诉了我们一个简单而深刻的道理。":"data:audio/mpeg;base64,","喂养":"data:audio/mpeg;base64,","小女孩每天都认真地喂养自己的小猫。":"data:audio/mpeg;base64,","群":"data:audio/mpeg;base64,","一群孩子在公园里高兴地做游戏。":"data:audio/mpeg;base64,","猴子":"data:audio/mpeg;base64,","树上的那只猴子正抱着一根树枝荡来荡去。":"data:audio/mpeg;base64,","宠物":"data:audio/mpeg;base64,","养宠物之前，要想清楚自己是否有时间照顾它。":"data:audio/mpeg;base64,","相处":"data:audio/mpeg;base64,","我们虽然来自不同的地方，却相处得很好。":"data:audio/mpeg;base64,","彼此":"data:audio/mpeg;base64,","在学习上，同学们应该彼此帮助。":"data:audio/mpeg;base64,","表情":"data:audio/mpeg;base64,","从他脸上的表情，我看出他很惊讶。":"data:audio/mpeg;base64,","行为":"data:audio/mpeg;base64,","在公共场所大声说话是不文明的行为。":"data:audio/mpeg;base64,","对方":"data:audio/mpeg;base64,","讨论问题时，我们应该认真听取对方的意见。":"data:audio/mpeg;base64,","蔬菜":"data:audio/mpeg;base64,","奶奶在院子里种了许多新鲜的蔬菜。":"data:audio/mpeg;base64,","粮食":"data:audio/mpeg;base64,","我们应该珍惜粮食，不要浪费。":"data:audio/mpeg;base64,","家庭":"data:audio/mpeg;base64,","在这个幸福的家庭里，每个人都关心着彼此。":"data:audio/mpeg;base64,","财产":"data:audio/mpeg;base64,","每个人都应该保护好自己的合法财产。":"data:audio/mpeg;base64,","消费":"data:audio/mpeg;base64,","购物时，我们应该理性消费。":"data:audio/mpeg;base64,","节省":"data:audio/mpeg;base64,","坐地铁去公司，可以节省很多时间。":"data:audio/mpeg;base64,","限制":"data:audio/mpeg;base64,","为了保证活动质量，这次活动限制了参加人数。":"data:audio/mpeg;base64,","猪":"data:audio/mpeg;base64,","爷爷以前在农村养过几头猪。":"data:audio/mpeg;base64,","调皮":"data:audio/mpeg;base64,","弟弟十分调皮，总喜欢躲在门后吓我。":"data:audio/mpeg;base64,","淘气":"data:audio/mpeg;base64,","那个淘气的孩子又偷偷地把我的帽子藏起来了。":"data:audio/mpeg;base64,","橡子":"data:audio/mpeg;base64,","孩子们在树下捡到了几颗橡子。":"data:audio/mpeg;base64,","果实":"data:audio/mpeg;base64,","到了秋天，树上的果实渐渐成熟了。":"data:audio/mpeg;base64,","不足":"data:audio/mpeg;base64,","由于准备不足，他这次没有通过考试。":"data:audio/mpeg;base64,","倒":"data:audio/mpeg;base64,","大家都说这个办法不好，我倒觉得可以试一试。":"data:audio/mpeg;base64,","馒头":"data:audio/mpeg;base64,","早饭时，他吃了一个馒头，喝了一碗粥。":"data:audio/mpeg;base64,","颗":"data:audio/mpeg;base64,","她从口袋里拿出一颗糖。":"data:audio/mpeg;base64,","似乎":"data:audio/mpeg;base64,","他今天似乎有点儿累，一直没怎么说话。":"data:audio/mpeg;base64,","吃亏":"data:audio/mpeg;base64,","买东西前多比较一下，就不容易吃亏。":"data:audio/mpeg;base64,","方式":"data:audio/mpeg;base64,","每个人都有适合自己的学习方式。":"data:audio/mpeg;base64,","安慰":"data:audio/mpeg;base64,","看到朋友难过，她轻声地安慰了几句。":"data:audio/mpeg;base64,","要不":"data:audio/mpeg;base64,","今天太晚了，要不我们明天再讨论吧。":"data:audio/mpeg;base64,","显得":"data:audio/mpeg;base64,","穿上这件衣服，她显得更年轻了。":"data:audio/mpeg;base64,","格外":"data:audio/mpeg;base64,","听说妈妈要来，她今天显得格外高兴。":"data:audio/mpeg;base64,","情景":"data:audio/mpeg;base64,","多年以后，我仍然记得当时的情景。":"data:audio/mpeg;base64,","哈":"data:audio/mpeg;base64,","哈，这个故事真有趣！":"data:audio/mpeg;base64,"};
function speak(text){stopAudio();const path=AUDIO_INDEX[text];if(!path){toast('未找到此内容的配套音频。');return}const generation=audioGeneration;const player=new Audio(path);playback=player;player.playbackRate=speed;player.onerror=()=>{if(generation===audioGeneration){$('ntc-voice-label').textContent='音频未加载';toast('无法加载音频，请确认 HTML 与 audio 文件夹一起保存或上传。')}};player.onended=()=>{if(playback===player)playback=null};player.play().then(()=>{if(generation!==audioGeneration){player.pause();return}$('ntc-voice-label').textContent='朗读：Xiaoxiao · 固定 MP3';}).catch(()=>{if(generation===audioGeneration)toast('音频暂时无法播放，请确认音频文件存在后再次点击。')})}
function backup(){const content=JSON.stringify({format:'ntc-hsk5-bai8-v3',profile:student},null,2);let url=URL.createObjectURL(new Blob([content],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download='HSK5_Bai8_TienDo.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),2000)}
function restore(){let input=document.createElement('input');input.type='file';input.accept='.json,application/json';input.addEventListener('change',async()=>{try{let v=JSON.parse(await input.files[0].text()),p=v.profile;if(v.format!=='ntc-hsk5-bai8-v3'||!p||typeof p.name!=='string'||typeof p.clas!=='string'||!Array.isArray(p.studied)||p.studied.some(id=>!Number.isInteger(id)||id<0||id>=43)||!p.memory)throw Error();if(!confirm('恢复第8课学习记录？当前记录将被替换。'))return;let id=store.active||'local';let clean=createStudent(p.name,p.clas);clean.studied=[...new Set(p.studied)];for(let k=0;k<43;k++)if(['remembered','review'].includes(p.memory[k]))clean.memory[k]=p.memory[k];if(p.bookmark&&Number.isInteger(p.bookmark.g)&&p.bookmark.g>=0&&p.bookmark.g<4&&Number.isInteger(p.bookmark.idx)&&p.bookmark.idx>=0&&p.bookmark.idx<group(p.bookmark.g).length)clean.bookmark=p.bookmark;for(let key of ['quizHistory','orderHistory'])if(Array.isArray(p[key]))clean[key]=p[key].filter(r=>r&&Array.isArray(r.answers)&&r.answers.every(a=>Number.isInteger(a.id)&&a.id>=0&&a.id<43&&typeof a.ok==='boolean'));clean.timeMs=Math.max(0,Number(p.timeMs)||0);store.profiles[id]=clean;store.active=id;student=clean;ui={page:5,g:0,idx:0,pinyin:false};save();render();toast('已恢复已学词语、复习状态与练习记录。')}catch(e){toast('无法读取有效的HSK5第8课学习记录。')}});input.click()}
root.addEventListener('click',event=>{let b=event.target.closest('button');if(!b||b.disabled)return;const data=b.dataset;if(data.audioWord!==undefined){speak(WORDS[+data.audioWord].w);return}if(data.audioExample!==undefined){speak(WORDS[+data.audioExample].s);return}if(data.page!==undefined){go(+data.page);return}if(data.group!==undefined){chooseGroup(+data.group);return}if(data.word!==undefined){let id=+data.word;ui.g=groupOf(id);ui.idx=id-ui.g*10;go(1);return}if(data.answer!==undefined){stopAudio();pickQuiz(+data.answer);return}if(data.chunk!==undefined){addChunk(+data.chunk);return}if(data.remove!==undefined){removeChunk(+data.remove);return}let a=data.action;if(!a)return;if(a==='stop'){stopAudio();return}switch(a){case'strokes':animateWriting();return;case'resume':ui.g=student.bookmark.g;ui.idx=student.bookmark.idx;go(1);return;case'pinyin':ui.pinyin=!ui.pinyin;break;case'prev-study':{let id=currentWord().id-1;ui.g=groupOf(id);ui.idx=id-ui.g*10;break}case'mark-study':stopAudio();markStudy();return;case'flip':student.flash.flipped=!student.flash.flipped;break;case'flash-all':if(!allLearned()){go(2);return}ui.page=2;startFlash('all');return;case'flash-weak':if(!allLearned()){go(2);return}ui.page=2;startFlash('weak');return;case'flash-prev':student.flash.at--;student.flash.flipped=false;break;case'flash-next':student.flash.at++;student.flash.flipped=false;break;case'quiz-page':go(3);return;case'order-page':go(4);return;case'stats-page':go(5);return;case'quiz-as-meaning':student.quiz.questions[student.quiz.at].type='meaning';break;case'quiz-next':stopAudio();nextQuiz();return;case'quiz-restart':startQuiz();return;case'quiz-retry':startQuiz(true,student.quiz.questions.filter(x=>x.picked!==x.correct).map(x=>x.id));return;case'order-undo':removeChunk(student.order.selected.length-1);return;case'order-clear':student.order.selected=[];break;case'order-check':checkOrder();return;case'order-next':stopAudio();nextOrder();return;case'order-restart':startOrder();return;case'order-retry':startOrder(student.order.answers.filter(x=>!x.ok).map(x=>x.id));return;case'backup':backup();return;case'restore':restore();return;default:return}save();render()});
root.addEventListener('change',event=>{if(event.target.id==='ntc-rate')speed=Number(event.target.value)});


let strokeWriters=[],strokeRun=0;
function clearWriting(){strokeRun++;for(const w of strokeWriters){w.pauseAnimation();}strokeWriters=[];}
function setupWriting(){const box=$('ntc-writing');if(!box)return;box.innerHTML='';for(const c of currentWord().w){const el=document.createElement('span');el.setAttribute('aria-label',c);box.appendChild(el);if(!STROKE_DATA[c]||typeof HanziWriter==='undefined'){el.textContent=c;if(!/[\u4e00-\u9fff]/.test(c)){el.style.width='24px';el.style.fontSize='30px';}continue;}strokeWriters.push(HanziWriter.create(el,c,{width:92,height:106,padding:3,strokeColor:'#a3455d',radicalColor:'#a3455d',outlineColor:'#ecd2db',strokeAnimationSpeed:0.7,delayBetweenStrokes:180,charDataLoader:()=>STROKE_DATA[c]}));}}
async function animateWriting(){const token=++strokeRun,list=[...strokeWriters];if(!list.length){toast('暂时无法显示笔顺。');return;}const button=root.querySelector('[data-action="strokes"]');if(button)button.disabled=true;try{for(const w of list)await w.hideCharacter({duration:0});for(const w of list){if(token!==strokeRun)return;await w.animateCharacter();}}finally{if(token===strokeRun&&button)button.disabled=false;}}

let lastTick=Date.now();setInterval(()=>{let now=Date.now();if(student&&!document.hidden){student.timeMs+=Math.min(now-lastTick,15000);save()}lastTick=now},15000);
window.addEventListener('pagehide',()=>{save();stopAudio()});
if(student&&ui.page>=2&&ui.page<=4&&allLearned()){if(ui.page===2&&!student.flash)startFlash('all',false);if(ui.page===3&&!student.quiz)startQuiz(false);if(ui.page===4&&!student.order)startOrder(null,false)}
save();render();if(!storageOK)toast('浏览器阻止保存数据，建议导出学习记录作为备份。');

